:root {
  --bg: #0f172a;
  --panel: #111827;
  --surface: #ffffff;
  --muted: #64748b;
  --text: #0b1220;
  --text-light: #f8fafc;
  --primary: #0051c3;
  --accent: #de5052;
  --accent-2: #f59e0b;
  --ring: rgba(0, 81, 195, 0.35);
  --radius: 14px;
  --shadow: 0 14px 35px rgba(2, 12, 34, 0.12);
  --max: 1140px;
}
* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
body {
  font-family: Inter, "Segoe UI", Roboto, sans-serif;
  color: var(--text);
  background: #f8fafc;
  line-height: 1.6;
}
h1, h2, h3, .logo {
  font-family: "Poppins", Inter, sans-serif;
  line-height: 1.2;
  margin: 0 0 .5rem;
}
a { color: inherit; text-decoration: none; }
.container { width: min(100% - 2rem, var(--max)); margin: 0 auto; }
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: .85rem 1.15rem;
  border-radius: 10px;
  font-weight: 600;
  border: 1px solid transparent;
  transition: .2s ease;
  min-height: 44px;
}
.btn-primary { background: var(--primary); color: #fff; }
.btn-primary:hover { filter: brightness(1.06); }
.btn-accent { background: var(--accent); color: #fff; }
.btn-accent:hover { filter: brightness(1.06); }
.btn-ghost { background: #fff; border-color: #dbe3ef; }
.site-header {
  position: sticky;
  top: 0;
  z-index: 40;
  background: rgba(255, 255, 255, 0.95);
  backdrop-filter: blur(8px);
  border-bottom: 1px solid #e6edf7;
}
.nav-wrap {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 74px;
}
.logo { font-size: 1.35rem; font-weight: 700; color: var(--primary); }
.nav-links {
  display: flex;
  gap: 1.25rem;
  align-items: center;
}
.nav-links a { font-weight: 500; color: #1f2a3d; }
.nav-links a:hover { color: var(--primary); }
.mobile-toggle {
  display: none;
  background: transparent;
  border: none;
  width: 44px;
  height: 44px;
  border-radius: 8px;
}
.mobile-toggle:focus-visible, .btn:focus-visible, input:focus-visible, textarea:focus-visible, select:focus-visible {
  outline: 3px solid var(--ring);
  outline-offset: 2px;
}
.mobile-drawer {
  position: fixed;
  inset: 0 0 0 auto;
  width: min(84vw, 320px);
  background: #fff;
  box-shadow: -8px 0 25px rgba(0,0,0,.15);
  transform: translateX(105%);
  transition: transform .3s ease;
  padding: 5rem 1.25rem 1.25rem;
  z-index: 60;
}
.mobile-drawer.open { transform: translateX(0); }
.backdrop {
  position: fixed;
  inset: 0;
  background: rgba(2,6,23,.45);
  opacity: 0;
  visibility: hidden;
  transition: .25s ease;
  z-index: 55;
}
.backdrop.show { opacity: 1; visibility: visible; }
.mobile-drawer a { display: block; padding: .9rem 0; border-bottom: 1px solid #e8edf6; font-weight: 600; }
.hero {
  padding: 5.5rem 0 4.5rem;
  background: radial-gradient(1200px 500px at 85% -20%, rgba(0,81,195,.18), transparent 55%),
              linear-gradient(180deg, #0b1532, #0f1d42 65%, #12244f);
  color: var(--text-light);
}
.hero-grid {
  display: grid;
  grid-template-columns: 1.1fr .9fr;
  gap: 2rem;
  align-items: center;
}
.hero h1 { font-size: clamp(2rem, 3.4vw, 3.4rem); margin-bottom: 1rem; }
.hero p { color: #d6e2ff; max-width: 60ch; }
.hero .actions { display: flex; gap: .75rem; flex-wrap: wrap; margin-top: 1.3rem; }
.card {
  background: #fff;
  border-radius: var(--radius);
  padding: 1.1rem;
  box-shadow: var(--shadow);
}
.section { padding: 4.2rem 0; }
.section h2 { font-size: clamp(1.55rem, 2.3vw, 2.4rem); margin-bottom: .7rem; }
.kicker { color: var(--primary); font-weight: 700; letter-spacing: .02em; text-transform: uppercase; font-size: .83rem; }
.grid-3 { display: grid; grid-template-columns: repeat(3,1fr); gap: 1rem; }
.grid-2 { display: grid; grid-template-columns: repeat(2,1fr); gap: 1rem; }
.feature-card { padding: 1.2rem; border: 1px solid #e6edf7; border-radius: var(--radius); background: #fff; }
.feature-card h3 { margin-top: .3rem; font-size: 1.05rem; }
.stats {
  background: #0b1328;
  color: #f8fafc;
  padding: 1.8rem 0;
}
.stats-grid { display: grid; grid-template-columns: repeat(4,1fr); gap: 1rem; text-align: center; }
.stat-value { font-size: clamp(1.4rem,2.5vw,2.2rem); font-weight: 800; }
.stat-label { color: #c8d8ff; font-size: .93rem; }
.testimonial-wrap { display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: .8rem; }
.carousel-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 1px solid #d9e3f2;
  background: #fff;
}
.pricing-switch {
  display: inline-flex;
  border: 1px solid #d9e3f2;
  border-radius: 999px;
  padding: .25rem;
  gap: .25rem;
  background: #fff;
}
.switch-btn { border: none; padding: .45rem .9rem; border-radius: 999px; background: transparent; font-weight: 600; min-height: 44px; }
.switch-btn.active { background: var(--primary); color: #fff; }
.price-grid { display: grid; grid-template-columns: repeat(3,1fr); gap: 1rem; margin-top: 1.2rem; }
.price-card { border: 1px solid #d9e3f2; border-radius: var(--radius); padding: 1.2rem; background: #fff; position: relative; }
.badge { position: absolute; top: .8rem; right: .8rem; background: #fef3c7; color: #92400e; font-size: .75rem; border-radius: 999px; padding: .2rem .55rem; }
.price { font-size: 2rem; font-weight: 800; margin: .4rem 0; }
.faq-item { border-bottom: 1px solid #e4ebf7; }
.faq-q {
  width: 100%;
  text-align: left;
  background: transparent;
  border: none;
  padding: 1rem 0;
  font-weight: 650;
  min-height: 44px;
}
.faq-a { display: none; padding: 0 0 1rem; color: #475569; }
.faq-item.open .faq-a { display: block; }
.cta-band {
  margin-top: 2.2rem;
  background: linear-gradient(135deg, #0051c3, #17398f);
  color: #fff;
  border-radius: 20px;
  padding: 2rem;
}
.footer { background: #0b1328; color: #d8e2ff; padding: 2rem 0; margin-top: 3rem; }
.footer-grid { display: grid; grid-template-columns: 1.3fr 1fr 1fr; gap: 1.2rem; }
.form-group { margin-bottom: .9rem; }
label { display: block; font-weight: 600; margin-bottom: .35rem; }
input, textarea, select {
  width: 100%;
  padding: .7rem .8rem;
  border: 1px solid #cfd9ea;
  border-radius: 10px;
  font: inherit;
  min-height: 44px;
}
.error { color: #b91c1c; font-size: .9rem; margin-top: .25rem; }
.success { background: #dcfce7; color: #166534; border: 1px solid #86efac; border-radius: 12px; padding: .8rem .9rem; margin-top: .8rem; }
@media (max-width: 900px) {
  .hero-grid, .grid-3, .grid-2, .price-grid, .stats-grid, .footer-grid { grid-template-columns: 1fr; }
  .nav-links { display: none; }
  .mobile-toggle { display: inline-flex; align-items: center; justify-content: center; }
}
EOF

